public class JwtUtils {

    public static String createJWT(ContractData data) {

        String jwt = null;

        try {
            // keys
            PublicKey encryptionKey = KeyStoreUtil.getContractEncryptionKey(); // use euroins.pub
            Key signingKey = KeyStoreUtil.getContractSigningKey(); // use issuer's signing key

            // Create the Claims, which will be the content of the JWT
            JwtClaims claims = new JwtClaims();
            claims.setIssuer("ORBIS_FINANCE");  // who creates the token and signs it
            claims.setAudience("EUROINS"); // to whom the token is intended to be sent
            claims.setExpirationTimeMinutesInTheFuture(10); // time when the token will expire (10 minutes from now)
//            claims.setGeneratedJwtId(); // a unique identifier for the token
//            claims.setIssuedAtToNow();  // when the token was issued/created (now)
//            claims.setNotBeforeMinutesInThePast(2); // time before which the token is not yet valid (2 minutes ago)
            claims.setSubject("contract"); // the subject/principal is whom the token is about

            // private claims
            data.toMap().forEach(claims::setClaim);

            // A JWT is a JWS and/or a JWE with JSON claims as the payload.
            // In this example it is a JWS nested inside a JWE
            // So we first create a JsonWebSignature object.
            JsonWebSignature jws = new JsonWebSignature();

            // The payload of the JWS is JSON content of the JWT Claims
            String claimsStr = claims.toJson();
            jws.setPayload(claimsStr);

            // The JWT is signed using the private key
            jws.setKey(signingKey);

            // Set the Key ID (kid) header which is needed to properly resolve verification key
            jws.setKeyIdHeaderValue("orbis_finance");

            // Set the signature algorithm on the JWT/JWS that will integrity protect the claims
            jws.setAlgorithmHeaderValue(AlgorithmIdentifiers.RSA_USING_SHA256);

            // Sign the JWS and produce the compact serialization, which will be the inner JWT/JWS
            // representation, which is a string consisting of three dot ('.') separated
            // base64url-encoded parts in the form Header.Payload.Signature
            String innerJwt = jws.getCompactSerialization();

            // The outer JWT is a JWE
            JsonWebEncryption jwe = new JsonWebEncryption();

            // The output of the RSA key agreement will encrypt a randomly generated content encryption key
            jwe.setAlgorithmHeaderValue(KeyManagementAlgorithmIdentifiers.RSA_OAEP_256);

            // The content encryption key is used to encrypt the payload
            // with a composite AES-CBC / HMAC SHA2 encryption algorithm
            String encAlg = ContentEncryptionAlgorithmIdentifiers.AES_128_CBC_HMAC_SHA_256;
            jwe.setEncryptionMethodHeaderParameter(encAlg);

            // We encrypt using public key
            jwe.setKey(encryptionKey);
            jwe.setKeyIdHeaderValue("encryptionkey");

            // A nested JWT requires that the cty (Content Type) header be set to "JWT" in the outer JWT
            jwe.setContentTypeHeaderValue("JWT");

            // The inner JWT is the payload of the outer JWT
            jwe.setPayload(innerJwt);

            // Produce the JWE compact serialization, which is the complete JWT/JWE representation,
            // which is a string consisting of five dot ('.') separated
            // base64url-encoded parts in the form Header.EncryptedKey.IV.Ciphertext.AuthenticationTag
            jwt = jwe.getCompactSerialization();

        } catch (Exception ex) {
        }

        return jwt;
    }
}

