struct Node{
    char symbol;
    int count;
};

void SiftUp(std::vector<Node*>& v, long i) {
    while (i > 0 && (v[i]->count > v[(i - 1) / 2]->count || v[i]->count == v[(i - 1) / 2]->count && v[i]->symbol > v[(i - 1) / 2]->symbol)) {
        std::swap(v[i], v[(i - 1) / 2]);
        i = (i - 1) / 2;
    }
}

void Insert(std::vector<Node*>& v, Node* n) {
    v.push_back(n);
    SiftUp(v, v.size() - 1);
}

void SiftDown(std::vector<Node*>& v, int i, int len) {
    long par = i;
    long left_kid = 2 * i + 1;
    long right_kid = 2 * i + 2;
    if (left_kid < len && (v[par]->count < v[left_kid]->count || v[par]->symbol < v[left_kid]->symbol && v[par]->count == v[left_kid]->count)) {
        par = left_kid;
    }
    if (right_kid < len && (v[par]->count < v[left_kid]->count || v[par]->symbol < v[left_kid]->symbol && v[par]->count == v[left_kid]->count)) {
        par = right_kid;
    }
    if (i != par) {
        std::swap(v[i], v[par]);
        SiftDown(v, par, len);
    }
}

int Extract_min( std::vector<Node*>& v) {
    int min = v[0]->count;
    v[0]->count = v[v.size() - 1]->count;
    v[0]->symbol = v[v.size() - 1]->symbol;
    v.pop_back();
    SiftDown(v, 0, v.size());
    return min;
}

